independent-practice.solution:
def first_repeat(names):
    seen = set()
    for name in names:
        if name in seen:
            return name
        seen.add(name)
    return ""

def most_common(text):
    words = text.split()
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    best = ""
    best_count = 0
    for word in words:
        if counts[word] > best_count:
            best = word
            best_count = counts[word]
    return best

def is_anagram(a, b):
    left = {}
    for ch in a.lower():
        if ch != " ":
            left[ch] = left.get(ch, 0) + 1
    right = {}
    for ch in b.lower():
        if ch != " ":
            right[ch] = right.get(ch, 0) + 1
    return left == right

def expand(glossary, words):
    table = {}
    for entry in glossary:
        gap = entry.find("=")
        table[entry[:gap]] = entry[gap + 1:]
    out = []
    for word in words:
        out.append(table.get(word, word))
    return out

def first_unique(text):
    counts = {}
    for ch in text:
        counts[ch] = counts.get(ch, 0) + 1
    for ch in text:
        if counts[ch] == 1:
            return ch
    return ""

